from ortools.constraint_solver import pywrapcp

def run(grouped, pair_active, pickup_disp):
    m=pywrapcp.RoutingIndexManager(4,1,[0],[3]); r=pywrapcp.RoutingModel(m)
    mat=[[1]*4 for _ in range(4)]; cb=r.RegisterTransitMatrix(mat); r.SetArcCostEvaluatorOfAllVehicles(cb)
    s=r.solver(); p=m.NodeToIndex(1); d=m.NodeToIndex(2)
    r.AddPickupAndDelivery(p,d); s.Add(r.VehicleVar(p)==r.VehicleVar(d)); s.Add(r.ActiveVar(p)==r.ActiveVar(d)) if pair_active else None
    r.AddDisjunction([d],0)
    if grouped: r.AddDisjunction([p],100,1)
    elif pickup_disp: r.AddDisjunction([p],0)
    q=pywrapcp.DefaultRoutingSearchParameters(); q.time_limit.seconds=2
    sol=r.SolveWithParameters(q)
    print(grouped,pair_active,pickup_disp,sol is not None, sol.Value(r.ActiveVar(p)) if sol else None)
